select count(1) from kb_routing_consumers
where consumer_code = #{consumerCode}

    and id != #{excludeId}

select code, sum(cnt) as total from ( select r.consumer_code as code, count(1) as cnt from kb_routing_rules r where r.consumer_code in
#{consumerCode}
group by r.consumer_code union all select tp.resource_code as code, count(1) as cnt from kb_resource_traffic_policies tp where tp.resource_type = 'ROUTING_CONSUMER' and tp.resource_code in
#{consumerCode}
group by tp.resource_code union all select qb.resource_code as code, count(1) as cnt from kb_resource_quota_bindings qb where qb.resource_type = 'ROUTING_CONSUMER' and qb.resource_code in
#{consumerCode}
group by qb.resource_code ) grouped group by code

mapper.update:
update kb_routing_consumers
set status = #{status}
where id = #{id}

update kb_routing_consumers
set secret_key = #{secretKey}
where id = #{id}
